CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, email VARCHAR(160) UNIQUE NOT NULL, phone VARCHAR(30), password VARCHAR(255) NOT NULL, role VARCHAR(10) NOT NULL, company_name VARCHAR(160), provider_type VARCHAR(60));
CREATE TABLE IF NOT EXISTS locations (id BIGINT PRIMARY KEY AUTO_INCREMENT, owner_id BIGINT NOT NULL, name VARCHAR(160), address VARCHAR(255), city VARCHAR(100), area VARCHAR(100), description TEXT, car_rate DECIMAL(10,2) DEFAULT 0, bike_rate DECIMAL(10,2) DEFAULT 0, ev_rate DECIMAL(10,2) DEFAULT 0);
CREATE TABLE IF NOT EXISTS slots (id BIGINT PRIMARY KEY AUTO_INCREMENT, location_id BIGINT NOT NULL, number VARCHAR(20) NOT NULL, type VARCHAR(10) NOT NULL, status VARCHAR(20) DEFAULT 'AVAILABLE', near_entrance BOOLEAN DEFAULT FALSE, UNIQUE(location_id,number));
CREATE TABLE IF NOT EXISTS vehicles (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, number VARCHAR(30), type VARCHAR(10), model VARCHAR(100));
CREATE TABLE IF NOT EXISTS bookings (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, vehicle_id BIGINT NOT NULL, location_id BIGINT NOT NULL, slot_id BIGINT NOT NULL, start_time DATETIME NOT NULL, end_time DATETIME NOT NULL, status VARCHAR(20) DEFAULT 'CONFIRMED', estimated_amount DECIMAL(10,2), checked_in DATETIME NULL, checked_out DATETIME NULL, final_amount DECIMAL(10,2) NULL);
CREATE TABLE IF NOT EXISTS payments (id BIGINT PRIMARY KEY AUTO_INCREMENT, booking_id BIGINT NOT NULL, amount DECIMAL(10,2), method VARCHAR(40) DEFAULT 'CASH', status VARCHAR(20) DEFAULT 'PAID', transaction_id VARCHAR(60), paid_at DATETIME DEFAULT CURRENT_TIMESTAMP);
